/**
 * @module features/requisicoes
 *
 * Feature de requisições de insumos: criação de pedidos entre lojas/fábrica,
 * separação digital (picking), relatórios de envio e consultor de demanda.
 */

export { default as RequisicaoPage } from './ui/Requisicao.page';
export { default as ConclusaoRequisicaoPage } from './ui/ConclusaoRequisicao.page';
export { default as PaginaPickingPage } from './ui/PaginaPicking.page';
export { ReportsModal } from './ui/ReportsModal';
export { AutoRequisitionWizard } from './ui/AutoRequisitionWizard';
export { CategorySelector } from './ui/CategorySelector';
export { DemandConsultant } from './ui/DemandConsultant';

import { useState, useEffect, useRef, useMemo } from "react";
import { printHTML } from '@/shared/lib/print';
import { Upload, Calculator, Sparkles, FileSpreadsheet, Loader2, Bot, CheckCircle2, ArrowRight, ArrowLeft, Zap, FileCheck, Printer, Trash2, Edit3, Plus, GripVertical, BarChart3, CheckCircle, Users, LogOut, ClipboardList, Store, Clock, Calendar, AlertTriangle, Truck, ScanBarcode } from "lucide-react";
import { useNavigate, useLocation } from "react-router-dom";
import {
  DndContext,
  closestCenter,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  DragEndEvent,
  DragStartEvent,
  DragOverlay,
} from '@dnd-kit/core';
import {
  arrayMove,
  SortableContext,
  sortableKeyboardCoordinates,
  verticalListSortingStrategy,
} from '@dnd-kit/sortable';
import {
  useSortable,
} from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { Progress } from "@/shared/ui/progress";
import { FormErrorBoundary } from "@/shared/ui/FormErrorBoundary";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/shared/ui/card";
import { Button } from "@/shared/ui/button";
import { Textarea } from "@/shared/ui/textarea";
import { Input } from "@/shared/ui/input";
import { Label } from "@/shared/ui/label";
import { Badge } from "@/shared/ui/badge";
import { Separator } from "@/shared/ui/separator";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/shared/ui/tabs";
import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from "@/shared/ui/accordion";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/shared/ui/dialog";
import { StoreSelector, normalizeStoreName, getStoreLabel } from "@/components/stores/StoreSelector";
import { toast } from "sonner";
import { supabase } from "@/integrations/supabase/client";
import { ReportsModal } from "@/features/notas-fiscais/ui/ReportsModal";
import { ReasoningDisplay } from "@/components/ReasoningDisplay";
import { useAuth } from "@/shared/hooks/useAuth";

import { normalizeName, similarity } from "@/shared/lib/stringUtils";
import { bestCatalogMatch } from "@/shared/lib/productMatch";
import { detectCategory, getEffectiveCategory, shouldPreserveCategory } from "@/shared/lib/category";
import { CategorySelector } from "@/features/requisicoes/ui/CategorySelector";
import { AutoRequisitionWizard } from "@/features/requisicoes/ui/AutoRequisitionWizard";
import { StoreExpeditionTracker } from "@/features/logistica/ui/StoreExpeditionTracker";
import { parseDateFromTitle, coerceISODateString, formatDateDDMMYY, getCurrentLocalDate, getTomorrowLocalDate, validateDeliveryDate, cn } from "@/shared/lib/utils";
import { useDebouncedCallback } from "@/shared/hooks/useDebounce";
import { useIsMobile, useIsTablet } from "@/shared/hooks/use-mobile";
import { usePermissions } from "@/shared/hooks/usePermissions";
import { useStore } from "@/shared/contexts/StoreContext";
import { PermissionBlur } from "@/shared/ui/PermissionBlur";
import { calculateContextAndCallAI } from "@/lib/ai/stockCalculator";
import { useMiaRequisicaoActions } from '@/features/mia/model/hooks';
import salesDataRaw from '../data/sales_history.json';
import { handleError } from '@/shared/lib/error-handler';
import { wideDebug, wideInfo, wideWarn, wideError } from '@/shared/lib/telemetry/wide-events';


// AIProcessedItem importado de SortableItem.tsx

interface ActiveSeparation {
  id: string;
  requester_name: string;
  preparer_name: string;
  store_requester: string;
  store_preparer: string;
  order_date: string;
  received_date: string;
  status: string;
  created_at: string;
  updated_at: string;
  total_items: number;
  completed_items: number;
  active_users: Array<{
    user_name: string;
    last_seen: string;
  }>;
}

interface ActiveReviewSession {
  session_id: string;
  requester_name: string;
  preparer_name: string;
  store_requester: string;
  store_preparer: string;
  order_date: string;
  received_date: string;
  status: 'editing' | 'separating';
  created_at: string;
  updated_at: string;
  total_items: number;
  completed_items: number;
  has_active_separation: boolean;
  separation_id?: string;
}

import { SortableItem, type AIProcessedItem } from "@/features/requisicoes/ui/SortableItem";

import { useProductAliases, normalizeAlias } from "@/features/produtos/model/useProductAliases";

export default function Requisicao() {
  const { selectedStore } = useStore();
  const SESSIONS_DISABLED = true;
  const navigate = useNavigate();
  const location = useLocation();
  const isAgenteRepa = location.pathname === '/agente-repa';
  const isInSession = false as boolean;
  const globalSessionId = null as string | null;
  const exitSession = () => { };
  const enterSession = (_id?: string) => { };
  const { userProfile } = useAuth();
  const isMobile = useIsMobile();
  const isTablet = useIsTablet();
  const { isAdmin, canViewRequisicao } = usePermissions();
  const isLogistica = false;

  // Hook para aliases de produtos (aprendizado contínuo)
  const { addAlias, findProductByAlias, fetchAliases } = useProductAliases();

  const [manualRequestText, setManualRequestText] = useState("");
  const [allItems, setAllItems] = useState<AIProcessedItem[]>([]);
  // Manual Matching States
  const [isMatchModalOpen, setIsMatchModalOpen] = useState(false);
  const [unmatchedItems, setUnmatchedItems] = useState<AIProcessedItem[]>([]);

  const [synthesizerReview, setSynthesizerReview] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingStage, setProcessingStage] = useState('');
  const [processingProgress, setProcessingProgress] = useState(0);
  const [aiReasoningLive, setAiReasoningLive] = useState<string[]>([]);
  // Erro persistente do processamento manual (banner na aba de input) — não some como o toast.
  const [processingError, setProcessingError] = useState<string | null>(null);
  // Controla o abort do streaming da IA (botão Cancelar + watchdog de inatividade).
  const aiAbortRef = useRef<AbortController | null>(null);

  // Initialize with user profile data if available
  const [requesterName, setRequesterName] = useState(userProfile?.nome || "Colaborador");
  const [preparerName, setPreparerName] = useState("DAVI/PEDRO");
  const [storeRequester, setStoreRequester] = useState(userProfile?.unidade || userProfile?.metadata?.store_name || "ASA NORTE");
  const [storePreparer, setStorePreparer] = useState("Fábrica");
  const [orderDate, setOrderDate] = useState(getCurrentLocalDate());
  const [receivedDate, setReceivedDate] = useState(() => getTomorrowLocalDate());

  // Update effect for profile changes
  useEffect(() => {
    if (userProfile) {
      if (userProfile.nome) setRequesterName(userProfile.nome);
      if (userProfile.unidade) setStoreRequester(userProfile.unidade);
    }
  }, [userProfile]);
  const [showHistory, setShowHistory] = useState(false);
  const [showHistoryModal, setShowHistoryModal] = useState(false);
  const [historyFilter, setHistoryFilter] = useState<'all' | 'aprovada' | 'em_fila' | 'pendente' | 'rejeitada'>('em_fila');
  const [showReportsModal, setShowReportsModal] = useState(false);
  const [showActiveSeparationsModal, setShowActiveSeparationsModal] = useState(false);
  const [isLeaving, setIsLeaving] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [flowSource, setFlowSource] = useState<'auto' | 'text' | 'manual' | null>(isAgenteRepa ? 'auto' : null);

  // Expedition Tracker State
  const [showExpeditionTracker, setShowExpeditionTracker] = useState(false);
  const [activeExpeditionId, setActiveExpeditionId] = useState<string | null>(null);
  const [trackerStoreName, setTrackerStoreName] = useState<string>('');
  const [availableExpeditions, setAvailableExpeditions] = useState<any[]>([]);
  const [showExpeditionSelector, setShowExpeditionSelector] = useState(false);

  const handleCheckExpedition = async () => {
    try {
      // Find ALL active expeditions
      const { data: exps, error } = await supabase
        .from('expedicoes')
        .select('id, status, code, veiculo, created_at, requisicoes(count)')
        .in('status', ['separation', 'loading', 'dispatch', 'in_transit', 'unloading'])
        .order('created_at', { ascending: false });

      if (error) throw error;

      if (exps && exps.length > 0) {
        // ALWAYS show selector, even if there is only one
        setAvailableExpeditions(exps);
        setShowExpeditionSelector(true);
      } else {
        toast.info("Nenhuma expedição em andamento encontrada.");
      }
    } catch (e) {
      handleError(e, { domain: 'requisicoes', operation: 'checarExpedicao', showToast: false });
      toast.error("Erro ao buscar expedições.");
    }
  };

  const handleSelectExpedition = (expeditionId: string) => {
    setActiveExpeditionId(expeditionId);
    setTrackerStoreName(storeRequester || "Asa Sul");
    setShowExpeditionSelector(false);
    setShowExpeditionTracker(true);
  };

  // Auto AI States

  const [isWizardMode, setIsWizardMode] = useState(isAgenteRepa);
  const [loadingAutoAi, setLoadingAutoAi] = useState(false);
  // const [showAutoAiDateModal, setShowAutoAiDateModal] = useState(false); // Removed in favor of wizard
  const [loadingWordsIndex, setLoadingWordsIndex] = useState(0);
  const loadingWords = [
    "Analisando histórico de vendas...",
    "Verificando níveis de estoque...",
    "Calculando sugestão matemática...",
    "Aplicando regras de negócios...",
    "Consultando padrões de consumo...",
    "Gerando decisões executivas..."
  ];

  useEffect(() => {
    if (loadingAutoAi) {
      const interval = setInterval(() => {
        setLoadingWordsIndex((prev) => (prev + 1) % loadingWords.length);
      }, 2000);
      return () => clearInterval(interval);
    }
  }, [loadingAutoAi]);
  const [activeSeparations, setActiveSeparations] = useState<ActiveSeparation[]>([]);
  const [activeReviewSessions, setActiveReviewSessions] = useState<ActiveReviewSession[]>([]);
  const [loadingActiveSeparations, setLoadingActiveSeparations] = useState(false);
  // Estado do modal de Fila
  const [showQueueModal, setShowQueueModal] = useState(false);
  const [queueLoading, setQueueLoading] = useState(false);
  const [queueItems, setQueueItems] = useState<any[]>([]);
  // Estado para controlar se está na etapa de entrega
  const [isDeliveryStep, setIsDeliveryStep] = useState(false);
  // Estado para controlar a direção da animação (entrada/saída)
  const [isTransitioning, setIsTransitioning] = useState(false);
  const [transitionDirection, setTransitionDirection] = useState<'forward' | 'backward'>('forward');
  const [savedLists, setSavedLists] = useState<Array<{
    id: number;
    name: string;
    items: AIProcessedItem[];
    createdAt: string;
    requesterName: string;
    preparerName: string;
    storeRequester: string;
    storePreparer: string;
    orderDate: string;
    receivedDate: string;
    subtitle?: string;
  }>>([]);

  const [requisitionSubtitle, setRequisitionSubtitle] = useState("");

  // Sensores para drag and drop
  const sensors = useSensors(
    useSensor(PointerSensor),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  );

  // Estado para item ativo durante o drag (para DragOverlay)
  const [activeId, setActiveId] = useState<string | null>(null);
  const dropAnimation = { duration: 90, easing: "cubic-bezier(0.2, 0, 0, 1)" } as any;

  // Categorias customizadas (para permitir colunas vazias e edição de nomes)
  const [customCategories, setCustomCategories] = useState<string[]>([]);
  const [editingCategory, setEditingCategory] = useState<string | null>(null);
  const [editingCategoryValue, setEditingCategoryValue] = useState<string>('');

  const handleAddCustomCategory = (category: string) => {
    const name = (category || '').trim();
    if (!name) return;
    setCustomCategories(prev => Array.from(new Set([...prev, name])));
    toast.success(`Categoria "${name}" criada`);
  };

  const addCustomCategory = (name?: string) => {
    const base = (name || 'Nova Categoria').trim();
    if (!base) return;
    setCustomCategories(prev => Array.from(new Set([...prev, base])));
    setEditingCategory(base);
    setEditingCategoryValue(base);
    toast.success('Nova categoria criada');
  };

  const renameCategory = async (oldName: string, newName: string) => {
    const oldTrim = (oldName || '').trim();
    const newTrim = (newName || '').trim();
    if (!newTrim) {
      setEditingCategory(null);
      setEditingCategoryValue('');
      return;
    }
    if (oldTrim === newTrim) {
      setEditingCategory(null);
      setEditingCategoryValue('');
      return;
    }

    // Atualizar lista de categorias customizadas
    setCustomCategories(prev => Array.from(new Set(prev.map(c => (c === oldTrim ? newTrim : c)))));

    // Atualizar itens que pertencem à categoria renomeada
    const itemsToUpdateIds: string[] = [];
    setAllItems(prev => prev.map(i => {
      const cat = (i.category?.trim() || 'Geral');
      const man = (i.manualCategory || '').trim();
      if (cat === oldTrim || man === oldTrim) {
        itemsToUpdateIds.push(i.id);
        return { ...i, category: newTrim, manualCategory: newTrim };
      }
      return i;
    }));

    // Sincronizar na sessão ativa, se aplicável
    if (isSessionMode && currentSessionId && itemsToUpdateIds.length) {
      await Promise.allSettled(itemsToUpdateIds.map(id => updateSessionItem(id, { category: newTrim })));
    }

    // Sincronizar com o banco de dados se a requisição foi enviada
    if (currentRequisicaoId && itemsToUpdateIds.length > 0) {
      const numericIds = itemsToUpdateIds.map(id => Number(id)).filter(id => !Number.isNaN(id));
      if (numericIds.length > 0) {
        (supabase as any)
          .from('requisicoes_itens')
          .update({ category: newTrim })
          .in('id', numericIds)
          .then(({ error }) => {
            if (error) {
              handleError(error, { domain: 'requisicoes', operation: 'renomearCategoria', showToast: false });
              toast.error('Erro ao salvar renomeação de categoria');
            }
          });
      }
    }

    setEditingCategory(null);
    setEditingCategoryValue('');
    toast.success(`Categoria renomeada para "${newTrim}"`);
  };

  const removeCustomCategory = (name: string) => {
    const trimmed = (name || '').trim();
    if (!trimmed) return;
    // Verificar se categoria possui itens
    const hasItems = allItems.some(i => {
      const cat = (i.category?.trim() || 'Geral');
      const man = (i.manualCategory || '').trim();
      return cat === trimmed || man === trimmed;
    });
    if (hasItems) {
      toast.error('Não é possível deletar uma categoria com itens');
      return;
    }
    setCustomCategories(prev => prev.filter(c => c !== trimmed));
    if (editingCategory === trimmed) {
      setEditingCategory(null);
      setEditingCategoryValue('');
    }
    toast.success(`Categoria "${trimmed}" deletada`);
  };

  // Formatação consistente em padrão brasileiro (dd/MM/yyyy HH:mm), timezone São Paulo
  const formatDateTimeBr = (value?: string | null) => {
    if (!value) return '';
    const d = new Date(value);
    if (isNaN(d.getTime())) return '';
    return new Intl.DateTimeFormat('pt-BR', {
      day: '2-digit', month: '2-digit', year: 'numeric',
      hour: '2-digit', minute: '2-digit', hour12: false,
      timeZone: 'America/Sao_Paulo'
    }).format(d);
  };

  const getQueueTimestamp = (req: any) => {
    const v = req?.enqueued_at ?? req?.enqueuedAt ?? req?.created_at ?? req?.createdAt ?? null;
    return formatDateTimeBr(v) || '—';
  };

  // Função para gerar ID único
  const generateId = () => Math.random().toString(36).substr(2, 9);

  // Estado para controlar a sincronização em tempo real
  const [realtimeChannel, setRealtimeChannel] = useState<any>(null);

  // Estados para sessões ativas
  const [isSessionMode, setIsSessionMode] = useState(false);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);

  // Hooks de sessão ativa
  const currentSession: any = null;
  const sessionItems: any[] = [];
  const sessionLoading = false;
  const createSession = async (..._args: any[]) => null as any;
  const loadSession = async (..._args: any[]) => false as boolean;
  const updateSession = async (..._args: any[]) => false as boolean;
  const updateSessionItem = async (..._args: any[]) => false as boolean;
  const addSessionItem = async (..._args: any[]) => null as any;
  const removeSessionItem = async (..._args: any[]) => false as boolean;
  const finalizeSession = async (..._args: any[]) => false as boolean;
  const getItemsAsAIProcessed = () => [] as any[];

  const filteredSavedLists = useMemo(() => {
    if (historyFilter === 'all') return savedLists;
    return savedLists.filter((l: any) => (l.status || 'pendente') === historyFilter);
  }, [savedLists, historyFilter]);

  // Hook otimizado para sincronização
  const syncItem = async (..._args: any[]) => { };
  const clearSyncCache = () => { };

  // Callbacks para realtime
  const handleSessionUpdate = (session: ActiveSessionData) => {
    // Atualizar dados da sessão se necessário
    wideDebug('requisicao.sessao_atualizada', 'Sessao atualizada em tempo real', { domain: 'requisicoes', attributes: { sessionId: session.session_id, status: session.status } });

    // Se a sessão foi finalizada ou removida, limpar estado local
    if (session.status === 'completed' || session.status === 'deleted') {
      wideDebug('requisicao.sessao_finalizada', 'Sessao finalizada/removida, limpando estado local', { domain: 'requisicoes' });
      setIsSessionMode(false);
      setCurrentSessionId(null);
      setAllItems([]);
      // Também sair da sessão no contexto global se ainda estivermos nela
      if (isInSession && globalSessionId === session.session_id) {
        exitSession();
      }
    }

    // Se a sessão ainda está ativa mas não estamos mais nela no contexto global,
    // atualizar estado local para refletir isso
    if (!isInSession && isSessionMode && currentSessionId === session.session_id) {
      wideDebug('requisicao.sessao_desconectada', 'Nao estamos mais na sessao, atualizando estado local', { domain: 'requisicoes' });
      setIsSessionMode(false);
      setCurrentSessionId(null);
    }
  };

  const handleItemUpdate = (item: ActiveSessionItem) => {
    // Atualizar item na lista local usando id como identificador estável
    setAllItems(prev =>
      prev.map(localItem =>
        localItem.id === item.id
          ? {
            ...localItem,
            name: editingNameIdsRef.current.has(item.id) ? localItem.name : item.item_name,
            requested: item.requested_quantity,
            sent: editingQuantityIdsRef.current.has(item.id) ? localItem.sent : item.sent_quantity,
            observation: editingObservationIdsRef.current.has(item.id) ? localItem.observation : item.observation,
            is_separated: item.is_separated,
            separated_by: item.separated_by,
            category: item.category ?? localItem.category ?? detectCategory(item.item_name)
          }
          : localItem
      )
    );
    wideDebug('requisicao.item_atualizado_realtime', 'Item atualizado via realtime', { domain: 'requisicoes', attributes: { itemName: item.item_name } });
  };

  const handleItemInsert = (item: ActiveSessionItem) => {
    // Evitar inserir duplicado caso já exista
    setAllItems(prev => {
      const existingIndex = prev.findIndex(i => i.id === item.id);
      const payloadName = editingNameIdsRef.current.has(item.id) ? prev[existingIndex]?.name : item.item_name;
      const payloadSent = editingQuantityIdsRef.current.has(item.id) ? prev[existingIndex]?.sent : item.sent_quantity;
      const payloadObs = editingObservationIdsRef.current.has(item.id) ? prev[existingIndex]?.observation : item.observation;
      if (existingIndex !== -1) {
        const updated = [...prev];
        updated[existingIndex] = {
          ...updated[existingIndex],
          name: payloadName ?? updated[existingIndex].name,
          requested: item.requested_quantity,
          sent: payloadSent ?? updated[existingIndex].sent,
          observation: payloadObs ?? updated[existingIndex].observation,
          is_separated: item.is_separated,
          separated_by: item.separated_by,
          category: item.category ?? updated[existingIndex].category ?? detectCategory(payloadName ?? item.item_name)
        };
        return updated;
      }
      const newItem: AIProcessedItem = {
        id: item.id,
        name: payloadName ?? item.item_name,
        requested: item.requested_quantity,
        sent: item.sent_quantity,
        observation: item.observation,
        is_separated: item.is_separated,
        separated_by: item.separated_by,
        category: item.category ?? detectCategory(payloadName ?? item.item_name)
      };
      return [...prev, newItem];
    });
  };

  const handleItemDelete = (itemId: string) => {
    // Remover item da lista local pelo id
    setAllItems(prev => prev.filter(item => item.id !== itemId));
  };

  // Hook de realtime para sessões
  const updateUserPresence = async (..._args: any[]) => { };

  const [isRealtimeConnected, setIsRealtimeConnected] = useState(false);
  const [editingNameIds, setEditingNameIds] = useState<Set<string>>(new Set());
  const [editingQuantityIds, setEditingQuantityIds] = useState<Set<string>>(new Set());
  const [editingObservationIds, setEditingObservationIds] = useState<Set<string>>(new Set());

  // Refs para evitar closures desatualizadas nos handlers de realtime
  const editingNameIdsRef = useRef<Set<string>>(new Set());
  const editingQuantityIdsRef = useRef<Set<string>>(new Set());
  const editingObservationIdsRef = useRef<Set<string>>(new Set());

  // Handlers para controlar lock de edição de nome
  const onNameFocus = (id: string) => {
    setEditingNameIds(prev => {
      const next = new Set([...prev, id]);
      editingNameIdsRef.current = next;
      return next;
    });
  };

  const onNameBlur = (id: string) => {
    setEditingNameIds(prev => {
      const next = new Set(prev);
      next.delete(id);
      editingNameIdsRef.current = next;
      return next;
    });
  };

  // Handlers para lock de edição de quantidade enviada
  const onQuantityFocus = (id: string) => {
    setEditingQuantityIds(prev => {
      const next = new Set([...prev, id]);
      editingQuantityIdsRef.current = next;
      return next;
    });
  };

  const onQuantityBlur = (id: string) => {
    setEditingQuantityIds(prev => {
      const next = new Set(prev);
      next.delete(id);
      editingQuantityIdsRef.current = next;
      return next;
    });
  };

  // Handlers para lock de edição de observação
  const onObservationFocus = (id: string) => {
    setEditingObservationIds(prev => {
      const next = new Set([...prev, id]);
      editingObservationIdsRef.current = next;
      return next;
    });
  };

  const onObservationBlur = (id: string) => {
    setEditingObservationIds(prev => {
      const next = new Set(prev);
      next.delete(id);
      editingObservationIdsRef.current = next;
      return next;
    });
  };

  // Estados para o reasoning da IA
  const [showReasoning, setShowReasoning] = useState(false);
  const [reasoningContent, setReasoningContent] = useState('');

  // Estados para o thinking process em tempo real
