  }, [requisicaoId]);

  useEffect(() => {
    if (requisicaoId) {
      carregarDados();

      // === PADRONIZAÇÃO DE STATUS: Marcar como "em_progresso" quando entrar na separação ===
      // Isso garante que requisições mudem de "em_fila" para "em_progresso" automaticamente
      const updateStatusToEmProgresso = async () => {
        try {
          // Só atualiza se o status atual for 'em_fila' (nunca iniciada)
          const { data: currentReq } = await supabase
            .from('requisicoes' as any)
            .select('status')
            .eq('id', requisicaoId)
            .single();

          if (currentReq) {
            // Handle legacy 'pendente' or other variations by normalizing first
            // If it's NOT finished and NOT already in progress, then we start it.
            const normalized = normalizeRequisicaoStatus(currentReq.status);

            // Specifically check for 'em_fila' (pending) state.
            // Note: 'normalizeRequisicaoStatus' maps unknown strings to 'em_fila', so this covers 'pendente', null, etc.
            if (normalized === 'em_fila') {
              await supabase
                .from('requisicoes' as any)
                .update({ status: 'em_progresso' })
                .eq('id', requisicaoId);
              wideDebug('picking.status_atualizado', `Requisicao ${requisicaoId} atualizada para em_progresso`, { domain: 'requisicoes', attributes: { requisicaoId } });
            }
          }
        } catch (error) {
          handleError(error, { domain: 'requisicoes', operation: 'atualizarStatusEmProgresso', showToast: false });
        }
      };

      updateStatusToEmProgresso();
    }
  }, [requisicaoId, carregarDados]);

  // Cleanup: limpa todos os timers de debounce pendentes ao desmontar
  useEffect(() => {
    const timers = manualQuantityTimers.current;
    const exits = pendingExits.current;
    return () => {
      timers.forEach((t) => clearTimeout(t));
      timers.clear();
      exits.forEach((t) => clearTimeout(t));
      exits.clear();
    };
  }, []);

  useEffect(() => {
    const setupPresence = async () => {
      if (!requisicaoId || !user) return;
      const { data: profile } = await supabase
        .from('profiles' as any)
        .select('nome, username')
        .eq('user_id', user.id)
        .single();

      const nome =
        (profile as ProfileRow)?.nome ||
        (profile as ProfileRow)?.username ||
        'Usuário';
      setMyProfileName(nome);
      const color = colorForUser(user.id);
      const channel = supabase.channel(`separacao-${requisicaoId}`, {
        config: {
          presence: { key: user.id },
          broadcast: { self: true, ack: true },
        },
      });
      channelRef.current = channel;

      type PresenceMeta = { nome: string; color: string; joined_at: string };
      channel.on('presence', { event: 'sync' }, () => {
        const state = channel.presenceState() as Record<string, PresenceMeta[]>;
        const list: Array<{
          user_id: string;
          nome: string;
          color: string;
          joined_at: string;
        }> = [];
        const seenUsers = new Set<string>(); // Deduplication Set

        Object.entries(state).forEach(([uid, metas]) => {
          // Take the first meta for this UID to prevent duplicate cards
          if (metas.length > 0 && !seenUsers.has(uid)) {
            const meta = metas[0];
            list.push({
              user_id: uid,
              nome: meta.nome,
              color: meta.color,
              joined_at: meta.joined_at,
            });
            seenUsers.add(uid);
          }
        });
        setPresence(list);
      });

      // Removed redundant 'join' and 'leave' listeners that were causing duplicate/generic logs.
      // We rely on explicit 'user_event' broadcasts for entry/exit to control the message better.

      // Log Buffering references to prevent flicker (pendingExits declared at component level)

      type UserEventPayload = {
        text: string;
        color?: string;
        user_name?: string;
      };
      channel.on(
        'broadcast',
        { event: 'user_event' },
        ({ payload }: { payload: UserEventPayload }) => {
          if (!payload?.text) return;

          const lowerText = payload.text.toLowerCase();
          // Check if this is an "Exit" event (by text convention)
          // We match "saiu" or "saiu da separação"
          const isExit = lowerText.includes('saiu');
          const isEntry =
            lowerText.includes('entrou') || lowerText.includes('retornou');

          // Extract username if possible (assuming simple format "Name ...")
          const subjectName = payload.user_name || payload.text.split(' ')[0];

          if (isExit && subjectName) {
            // Buffer Exit
            if (pendingExits.current.has(subjectName)) {
              clearTimeout(pendingExits.current.get(subjectName)!);
            }

            const timeoutId = setTimeout(() => {
              pendingExits.current.delete(subjectName);
              pushLog(payload.text, payload.color, false); // Already persisted by sender logically
            }, 10000); // 10s buffer for UI notification

            pendingExits.current.set(subjectName, timeoutId);
            return;
          }

          if (isEntry && subjectName) {
            // Check if we have a pending exit for this user
            if (pendingExits.current.has(subjectName)) {
              // He returned quickly! Cancel the exit.
              wideDebug('picking.presence_exit_cancelado', `Cancelando saida de ${subjectName} por retorno rapido`, { domain: 'requisicoes', attributes: { subjectName } });
              clearTimeout(pendingExits.current.get(subjectName)!);
              pendingExits.current.delete(subjectName);
              // And suppress THIS entry log too?
              // Yes, if we hid the exit, we should hide the re-entry to silence the flicker completely.
              return;
            }
          }

          // Normal log (or Entry without pending exit)
          pushLog(payload.text, payload?.color, false); // False because sender persists
        },
      );

      channel.subscribe(async (status: string) => {
        if (status === 'SUBSCRIBED') {
          channel.track({ nome, color, joined_at: new Date().toISOString() });

          // --- Intelligent Entry Logic (Self-Healing) ---
          try {
            // 1. Check most recent log for THIS user
            const { data: recentLogs } = await supabase
              .from('expedicao_logs' as any)
              .select('id, title, created_at, description')
              .eq('requisicao_id', requisicaoId)
              .eq('user_name', nome)
              .order('created_at', { ascending: false })
              .limit(5);

            const lastLog = recentLogs?.[0];
            const nowMs = Date.now();

            let isRefresh = false;

            if (lastLog) {
              const logTime = new Date(lastLog.created_at).getTime();
              const diffSec = (nowMs - logTime) / 1000;

              // If last log was "Saiu" and less than 45 seconds ago -> It's a refresh/flicker
              if (
                (lastLog.title === 'Saiu' ||
                  lastLog.description?.includes('saiu')) &&
                diffSec < 45
              ) {
                isRefresh = true;

                // SELF HEALING: Delete the "Saiu" log so history looks continuous
                wideDebug('picking.healing_flicker_exit', 'Removendo log de saida por flicker', { domain: 'requisicoes', attributes: { logId: lastLog.id } });
                await supabase
                  .from('expedicao_logs' as any)
                  .delete()
                  .eq('id', lastLog.id);
              }
            }

            if (isRefresh) {
              // If it was a refresh, we deleted the 'Exit'.
              // We should NOT log 'Entrou' again, to maintain the appearance that he never left.
              // However, we MUST broadcast 'user_event' 'entrou/retornou' so OTHER clients know we are back
              // (and can cancel their pending exit UI buffers).

              // Actually, if we deleted the DB log, the persistent history is fixed.
              // The realtime broadcast is needed to cancel the UI buffer on other screens.
              // We send "Retornou" or just "Entrou".
              const healText = `${nome} retornou`;
              channel.send({
                type: 'broadcast',
                event: 'user_event',
                payload: { text: healText, color, user_name: nome },
              });

              // Do NOT persist locally.
              wideDebug('picking.refresh_detectado', 'Refresh detectado: log curado, entrada suprimida da persistencia', { domain: 'requisicoes' });
            } else {
              // Not a refresh (or > 45s).
              // Check if user has ANY history to decide "Entrou" vs "Retornou".
              const hasHistory = recentLogs && recentLogs.length > 0; // He existed before
              const actionVerb = hasHistory ? 'retornou' : 'entrou'; // Lowercase for sentence
              const titleVerb = hasHistory ? 'Retornou' : 'Entrou';

              const entryText = `${nome} ${actionVerb}${hasHistory ? '' : ' na separação'}`;

              // Broadcast for others
              channel.send({
                type: 'broadcast',
                event: 'user_event',
                payload: { text: entryText, color, user_name: nome },
              });

              // Persist
              await supabase.from('expedicao_logs' as any).insert({
                requisicao_id: Number(requisicaoId),
                title: titleVerb,
                description: entryText,
                type: 'info',
                user_name: nome,
                metadata: {
                  action: 'user_entered',
                  color,
                  timestamp: new Date().toISOString(),
                },
              });

              // Local UI (no need, subscription handles INSERT event or broadcast handles it?)
              // Broadcast listener handles UI.
            }
          } catch (err) {
            handleError(err, { domain: 'requisicoes', operation: 'entryLogic', showToast: false });
            // Fallback
            const entryText = `${nome} entrou`;
            channel.send({
              type: 'broadcast',
              event: 'user_event',
              payload: { text: entryText, color, user_name: nome },
            });
          }
        }
      });

      const onBeforeUnload = () => {
        try {
          const exitText = `${nome} saiu da separação`;
          channel.send({
            type: 'broadcast',
            event: 'user_event',
            payload: { text: exitText, user_name: nome },
          });
          channel.untrack();
        } catch (e) {
          handleError(e, { domain: 'requisicoes', operation: 'beforeUnload', showToast: false });
        }
      };
      window.addEventListener('beforeunload', onBeforeUnload);

      return () => {
        window.removeEventListener('beforeunload', onBeforeUnload);
        try {
          // Component unmount (navigation or strict release)
          // We persist "Saiu" here.
          // IF the user is refreshing, this log will be created, but the Logic in SUBSCRIBED (above)
          // will catch it and DELETE it if they return quickly.
          const exitText = `${nome} saiu da separação`;
          channel.send({
            type: 'broadcast',
            event: 'user_event',
            payload: { text: exitText, user_name: nome },
          });
          channel.untrack();

          // Persist exit to DB
          supabase
            .from('expedicao_logs' as any)
            .insert({
              requisicao_id: Number(requisicaoId),
              title: 'Saiu',
              description: exitText,
              type: 'info',
              user_name: nome,
              metadata: {
                action: 'user_exited',
                timestamp: new Date().toISOString(),
              },
            })
            .then(() => {})
            .catch((err: unknown) => handleError(err, { domain: 'requisicoes', operation: 'exitLogPersist', showToast: false }));
        } catch (e) {
          handleError(e, { domain: 'requisicoes', operation: 'cleanupPresence', showToast: false });
        }
        supabase.removeChannel(channel);
        // Limpa a ref apenas se ainda apontar para ESTE canal (evita sobrescrever
        // uma nova instância criada pelo re-run do effect).
        if (channelRef.current === channel) {
          channelRef.current = null;
        }
      };
    };

    // Controle de vida do effect: se o cleanup rodar antes do setupPresence resolver,
    // asyncCleanup ainda será null, mas aborted=true fará o setup cleanup rodar
    // assim que ficar disponível.
    let aborted = false;
    let asyncCleanup: (() => void) | null = null;
    setupPresence().then((cleanup) => {
      if (cleanup) {
        if (aborted) {
          // Cleanup chegou tarde demais — executar agora
          cleanup();
        } else {
          asyncCleanup = cleanup;
        }
      }
    });

    return () => {
      aborted = true;
      if (asyncCleanup) {
        asyncCleanup();
      }
      // Se o setupPresence ainda não resolveu, o .then() acima cuidará do cleanup
      // assim que resolver (via verificação de `aborted`).
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [requisicaoId, user]);

  // Persistent Logs Fetch
  useEffect(() => {
    if (!requisicaoId) return;
    const fetchPersistentLogs = async () => {
      try {
        const { data, error } = await supabase
          .from('expedicao_logs' as any)
          .select('id, description, created_at, user_name, type, metadata')
          .eq('requisicao_id', requisicaoId)
          .order('created_at', { ascending: false })
          .limit(50);

        if (error) throw error;

        if (data) {
          const mappedLogs = (data as AuditLogRow[]).map((log) => ({
            id: log.id,
            text: log.description || 'Evento sem descrição',
            ts: log.created_at,
            user: log.user_name,
            type: log.type,
          }));
          setEventLogs((prev) => {
            // Merge preventing duplicates
            const existingIds = new Set(prev.map((p) => p.id));
            const newLogs = mappedLogs.filter((l) => !existingIds.has(l.id));
            return [...prev, ...newLogs].sort(
              (a, b) => new Date(b.ts).getTime() - new Date(a.ts).getTime(),
            );
          });
        }
      } catch (e) {
        handleError(e, { domain: 'requisicoes', operation: 'buscarLogsPersistentes', showToast: false });
      }
    };
    fetchPersistentLogs();

    // Subscribe to new logs
    const logChannel = supabase
      .channel(`logs-${requisicaoId}`)
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'expedicao_logs',
          filter: `requisicao_id=eq.${requisicaoId}`,
        },
        (payload) => {
          const newLog = payload.new;
          setEventLogs((prev) => {
            if (prev.some((p) => p.id === newLog.id)) return prev; // Avoid duplicates
            return [
              {
                id: newLog.id,
                text: newLog.description || 'Novo evento',
                ts: newLog.created_at,
                user: newLog.user_name,
                type: newLog.type,
              },
              ...prev,
            ];
          });
        },
      )
      .subscribe();

    return () => {
      supabase.removeChannel(logChannel);
    };
  }, [requisicaoId]);

  useEffect(() => {
    if (!requisicaoId) return;
    type RequisicaoItemRow = {
      id: number;
      nome_produto: string;
      quantidade_solicitada?: number | null;
      quantidade_enviada?: string | null;
      observacao?: string | null;
      category?: string | null;
      lote?: string | null;
      validade?: string | null;
    };
    const channel = supabase
      .channel(`separacao-items-${requisicaoId}`)
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'requisicoes_itens',
          filter: `requisicao_id=eq.${requisicaoId}`,
        },
        (payload: RealtimePostgresChangesPayload<RequisicaoItemRow>) => {
          if (!payload?.new && !payload?.old) return;
          const row = (payload.new || payload.old) as RequisicaoItemRow;
          const mapped: ItemPicking = {
            id: row.id,
            produto_nome: row.nome_produto,
            quantidade: row.quantidade_solicitada || 0,
            localizacao: '-',
            coletado:
              !!row.quantidade_enviada &&
              String(row.quantidade_enviada).trim() !== '',
            observacoes: row.observacao || '',
            quantidade_enviada: row.quantidade_enviada || '',
            category: row.category || 'Geral',
            lote: row.lote || '',
            validade: row.validade || '',
          };
          if (payload.eventType === 'INSERT') {
            setItens((prev) => {
              if (prev.some((it) => it.id === mapped.id)) return prev;
              const next = [...prev, mapped];
              return next.sort((a, b) => a.id - b.id);
            });
            return;
          }
          if (payload.eventType === 'UPDATE') {
            setItens((prev) =>
              prev.map((it) =>
                it.id === mapped.id
                  ? {
                      ...it,
                      produto_nome: mapped.produto_nome ?? it.produto_nome,
                      quantidade: mapped.quantidade ?? it.quantidade,
                      quantidade_enviada:
                        mapped.quantidade_enviada ?? it.quantidade_enviada,
                      coletado: mapped.coletado,
                      observacoes: mapped.observacoes ?? it.observacoes,
                      category: mapped.category ?? it.category,
                      lote: mapped.lote ?? it.lote,
                      validade: mapped.validade ?? it.validade,
                      selectedBatches: (() => {
                        const l = mapped.lote ?? it.lote;
                        if (!l) return it.selectedBatches;
                        const sb: Record<string, number> = {};
                        l.split(';').forEach((pair) => {
                          const [bId, bQty] = pair.split(':');
                          if (bId && bQty) sb[bId] = Number(bQty);
                        });
                        return sb;
                      })(),
                    }
                  : it,
              ),
            );
            return;
          }
          if (payload.eventType === 'DELETE') {
            setItens((prev) => prev.filter((it) => it.id !== mapped.id));
            return;
          }
        },
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [requisicaoId]);

  const colorForUser = (uid: string) => {
    const colors = [
      '#ef4444',
      '#f59e0b',
      '#10b981',
      '#3b82f6',
      '#8b5cf6',
      '#ec4899',
    ];
    let hash = 0;
    for (let i = 0; i < uid.length; i++)
      hash = (hash << 5) - hash + uid.charCodeAt(i);
    return colors[Math.abs(hash) % colors.length];
  };

  const pushLog = useCallback(
    async (text: string, color?: string, persist: boolean = true) => {
      // Debounce: Check if same message sent in last 2 seconds
      const now = Date.now();
      if (
        lastLogRef.current &&
        lastLogRef.current.text === text &&
        now - lastLogRef.current.time < 2000
      ) {
        return;
      }
      lastLogRef.current = { text, time: now };

      const id = Math.random().toString(36).slice(2);
      const timestamp = new Date().toISOString();

      setFeedNotifications((prev) =>
        [{ id, text, color }, ...prev].slice(0, 5),
      ); // Limit to 5
      setTimeout(() => {
        setFeedNotifications((current) => current.filter((n) => n.id !== id));
      }, 4000); // 4 seconds visibility

      if (persist && requisicaoId) {
        try {
          await supabase.from('expedicao_logs' as any).insert({
            requisicao_id: Number(requisicaoId),
            title: 'Ação',
            description: text,
            type: 'item_action',
            user_name: myProfileName || 'Sistema',
            metadata: { color, action_timestamp: timestamp },
          });
        } catch (e) {
          handleError(e, { domain: 'requisicoes', operation: 'persistirLog', showToast: false });
        }
      }
      // eslint-disable-next-line react-hooks/exhaustive-deps
    },
    [requisicaoId, myProfileName, isMobile],
  );

  const alternarItemColetado = async (itemId: number) => {
    const alvo = itens.find((i) => i.id === itemId);
    if (!alvo) {
      // Item foi removido por outra sessão (realtime). Nada a fazer.
      return;
    }
    const novoEstado = !alvo.coletado;

    // Calcula a quantidade ANTES do setState (snapshot estável)
    const jaTemQuantidade = parseFloat(alvo.quantidade_enviada || '0') > 0;
    const quantidadeFinal = novoEstado
      ? jaTemQuantidade
        ? alvo.quantidade_enviada || String(alvo.quantidade || 0)
        : String(alvo.quantidade || 0)
      : '';

    // Otimista: atualiza UI
    const previousState = { coletado: alvo.coletado, quantidade_enviada: alvo.quantidade_enviada };
    setItens((prev) =>
      prev.map((item) =>
        item.id === itemId
          ? { ...item, coletado: novoEstado, quantidade_enviada: quantidadeFinal }
          : item,
      ),
    );

    try {
      const { error: updateError } = await supabase
        .from('requisicoes_itens' as any)
        .update({ quantidade_enviada: quantidadeFinal })
        .eq('id', itemId);

      if (updateError) throw updateError;

      if (user) {
        const nomeUser = myProfileName;
        const nomeProd = alvo.produto_nome || 'Item';
        const color = colorForUser(user.id);
        const actionText = `${nomeUser} ${novoEstado ? 'marcou' : 'desmarcou'} ${nomeProd}`;

        channelRef.current?.send({
          type: 'broadcast',
          event: 'user_event',
          payload: { text: actionText, color },
        });
        pushLog(actionText, color);

        // Log persistente
        logExpeditionEvent(null, {
          title: `Item ${novoEstado ? 'Separado' : 'Desmarcado'}`,
          description: `${nomeUser} ${novoEstado ? 'marcou' : 'desmarcou'} "${nomeProd}"`,
          type: 'item_action',
          user_name: nomeUser,
          requisitionId: Number(requisicaoId),
          metadata: {
            item_id: itemId,
            item_name: nomeProd,
            checked: novoEstado,
            action: 'toggle_item',
          },
        });
      }
    } catch (e) {
      // Rollback otimista em caso de erro
      setItens((prev) =>
        prev.map((item) =>
          item.id === itemId
            ? { ...item, coletado: previousState.coletado, quantidade_enviada: previousState.quantidade_enviada }
            : item,
        ),
      );
      handleError(e, { domain: 'requisicoes', operation: 'alternarItemColetado', showToast: false });
      toast({
        title: 'Erro ao salvar',
        description: 'Não foi possível atualizar o item. Tente novamente.',
        variant: 'destructive',
      });
    }
  };

  const updateItemCategoria = async (itemId: number, categoria: string) => {
    setItens((prev) =>
      prev.map((i) => (i.id === itemId ? { ...i, category: categoria } : i)),
    );
    await supabase
      .from('requisicoes_itens' as any)
      .update({ category: categoria })
      .eq('id', itemId);
    setCustomCategories((prev) =>
      Array.from(new Set([...(prev || []), (categoria || 'Geral').trim()])),
    );
    if (user) {
      const alvo = itens.find((i) => i.id === itemId);
      const nomeUser = myProfileName;
      const color = colorForUser(user.id);
      channelRef.current?.send({
        type: 'broadcast',
        event: 'user_event',
        payload: {
          text: `${nomeUser} trocou categoria de ${alvo?.produto_nome || 'Item'} para ${categoria}`,
          color,
        },
