  const marcarNaoTem = async (itemId: number) => {
    setItens((prev) =>
      prev.map((i) =>
        i.id === itemId
          ? {
              ...i,
              quantidade_enviada: '0',
              observacoes: 'não tem',
              coletado: true,
            }
          : i,
