                            <RequisicaoChegada />
                          </DashboardLayout>
                        </ProtectedRoute>
                      }
                    />



                    <Route
                      path="/movimentacoes"
                      element={
                        <ProtectedRoute>
                          <DashboardLayout>
                            <Movimentacoes />
                          </DashboardLayout>
                        </ProtectedRoute>
                      }
                    />
                    <Route
                      path="/pronta-entrega"
                      element={
                        <PermissionProtectedRoute requiredPermission="view_pronta_entrega">
                          <DashboardLayout>
                            <ProntaEntregaPage />
                          </DashboardLayout>
                        </PermissionProtectedRoute>
                      }
                    />
                    <Route
                      path="/encomendas"
                      element={
                        <ProtectedRoute>
                          <DashboardLayout>
                            <Encomendas />
                          </DashboardLayout>
                        </ProtectedRoute>
                      }
                    />
                    <Route
                      path="/eventos"
                      element={
                        <ProtectedRoute>
                          <DashboardLayout>
                            <Eventos />
