import { useState, useEffect, useMemo } from 'react';
import { Button } from '@/shared/ui/button';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/shared/ui/card';
import {
  Bot,
  Calendar,
  ArrowRight,
  ArrowLeft,
  Loader2,
  Play,
  Layers,
  Search,
  CheckCircle2,
  Link as LinkIcon,
} from 'lucide-react';
import { Label } from '@/shared/ui/label';
import { Input } from '@/shared/ui/input';
import { Switch } from '@/shared/ui/switch';
import { ScrollArea } from '@/shared/ui/scroll-area';
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from '@/shared/ui/accordion';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/shared/ui/select';
import { supabase } from '@/integrations/supabase/client';
import { toast } from 'sonner';
import { Badge } from '@/shared/ui/badge';
import { DemandConsultant } from '@/features/requisicoes/ui/DemandConsultant';
import { format } from 'date-fns';
import { ptBR } from 'date-fns/locale';
import { SalesMappingModal } from './SalesMappingModal';
import { handleError } from '@/shared/lib/error-handler';

interface AutoRequisitionWizardProps {
  onBack: () => void;
  onConfirm: (
    storeId: number,
    targetDays: string[],
    selectedProducts: any[],
    storeName: string,
  ) => void;
  isLoading: boolean;
  loadingWordsIndex: number;
  loadingWords: string[];
  defaultStoreName: string;
}

interface ProductNode {
  id: number;
  nome: string;
  setor: string;
  codigo_interno: number;
  checked: boolean;
}

interface Store {
  id: number;
  nome: string;
}

interface SectorNode {
  name: string;
  products: ProductNode[];
  checked: boolean; // if all products in sector checked
}

export function AutoRequisitionWizard({
  onBack,
  onConfirm,
  isLoading,
  loadingWordsIndex,
  loadingWords,
  defaultStoreName,
}: AutoRequisitionWizardProps) {
  const [step, setStep] = useState<'day' | 'products'>('day');
  const [isMatchModalOpen, setIsMatchModalOpen] = useState(false);

  // Store & Date State
  const [stores, setStores] = useState<Store[]>([]);
  const [selectedStoreId, setSelectedStoreId] = useState<number | null>(null);
  const [selectedDay, setSelectedDay] = useState<string>('');
  const [coverageDays, setCoverageDays] = useState<number>(1);

  // Product Selection State
  const [loadingProducts, setLoadingProducts] = useState(false);
  const [sectors, setSectors] = useState<SectorNode[]>([]);
  const [searchTerm, setSearchTerm] = useState('');

  const days = [
    'Segunda-feira',
    'Terça-feira',
    'Quarta-feira',
    'Quinta-feira',
    'Sexta-feira',
    'Sábado',
    'Domingo',
  ];

  useEffect(() => {
    loadStores();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const loadStores = async () => {
    const { data } = await supabase
      .from('lojas')
      .select('id, nome')
      .eq('ativo', true)
      .order('id');
    if (data) {
      setStores(data);
      // Try to match default store
      if (defaultStoreName) {
        const match = data.find((s) =>
          s.nome.toLowerCase().includes(defaultStoreName.toLowerCase()),
        );
        if (match) setSelectedStoreId(match.id);
      }
    }
  };

  // Calculate Target Days Array
  const targetDays = useMemo(() => {
    if (!selectedDay) return [];
    const startIndex = days.indexOf(selectedDay);
    if (startIndex === -1) return [];

    const result = [];
    for (let i = 0; i < coverageDays; i++) {
      const index = (startIndex + i) % 7;
      result.push(days[index]);
    }
    return result;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedDay, coverageDays]);

  useEffect(() => {
    if (step === 'products' && sectors.length === 0) {
      loadProducts();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [step]);

  const loadProducts = async () => {
    setLoadingProducts(true);
    try {
      // Fetch Sectors
      const { data: sectorsTable, error: sectorError } = await supabase
        .from('setores')
        .select('nome')
        .eq('ativo', true)
        .order('nome');

      if (sectorError) throw sectorError;

      // Fetch Products
      const { data: prods, error: prodError } = await supabase
        .from('produtos_master')
        .select('id, nome, setor, codigo_interno')
        .eq('ativo', true)
        .order('nome');

      if (prodError) throw prodError;

      // Build Tree
      // Primary grouping: Sector
      const sectorMap: Record<string, ProductNode[]> = {};

      // Initialize with all sectors from the table to ensure they appear
      sectorsTable?.forEach(s => {
        if (!sectorMap[s.nome]) sectorMap[s.nome] = [];
      });

      prods.forEach((prod) => {
        const setor = prod.setor || 'Outros';
        if (!sectorMap[setor]) sectorMap[setor] = [];

        sectorMap[setor].push({
          ...prod,
          checked: true
        });
      });

      const sectorNodes: SectorNode[] = Object.entries(sectorMap)
        .sort((a, b) => a[0].localeCompare(b[0]))
