Se nenhum item for suspeito, retorne exatamente: { "flags": [] }
Não escreva nada fora do JSON.`;

interface LlmResult {
  content: string;
  usage: { prompt_tokens?: number; completion_tokens?: number } | null;
}

async function callModel(prompt: string, model: string): Promise<LlmResult> {
  const apiKey = Deno.env.get('OPENROUTER_API_KEY');
  if (!apiKey) throw new Error('OPENROUTER_API_KEY not set');
  const res = await fetch('https://openrouter.ai/api/v1/chat/completions', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${apiKey}`,
      'Content-Type': 'application/json',
      'HTTP-Referer': 'https://momma-stock-insight.vercel.app',
      'X-Title': 'momma-match-review',
    },
    body: JSON.stringify({
      model,
      messages: [
        { role: 'system', content: SYSTEM_PROMPT },
        { role: 'user', content: prompt },
      ],
      temperature: 0,
      // Força JSON limpo (sem fences/preâmbulo) — melhora confiabilidade do modelo
      // primário (grok) e dos demais; o parse de fallback ainda cobre quem ignorar.
      response_format: { type: 'json_object' },
    }),
  });
  if (!res.ok) {
    const txt = await res.text().catch(() => '');
    throw new Error(`OpenRouter ${model}: ${res.status} ${txt}`);
  }
  const data = await res.json();
  return { content: data?.choices?.[0]?.message?.content ?? '', usage: data?.usage ?? null };
}

async function callWithFallback(prompt: string): Promise<{ content: string; model: string; usage: LlmResult['usage'] }> {
  let lastErr: unknown;
  for (const model of FALLBACK_MODELS) {
    try {
      const { content, usage } = await callModel(prompt, model);
      if (content && content.trim()) return { content, model, usage };
    } catch (err) {
      lastErr = err;
      console.warn('[review] model fail', model, err instanceof Error ? err.message : String(err));
    }
  }
  throw lastErr || new Error('Todos os modelos de fallback falharam');
}

function parseJson(content: string): unknown {
  let clean = content.trim();
  if (clean.startsWith('```')) {
    clean = clean.replace(/^```(?:json)?\s*/, '').replace(/\s*```$/, '');
  }
  return JSON.parse(clean);
}

serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response(null, { headers: corsHeaders });
  }

  const tracer = new EdgeTracer(req, { serviceName: 'gidape-edge-match-review' });
  const metrics = new EdgeMetrics({ serviceName: 'gidape-edge-match-review' });
  const rootSpan = tracer.startSpan('review-requisition-matches');

  try {
    const { items, productCatalog } = await req.json();
    if (!Array.isArray(items) || items.length === 0) {
      rootSpan.end();
      Promise.all([tracer.flush(), metrics.flush()]).catch(() => {});
      return new Response(JSON.stringify({ flags: [] }), {
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      });
    }
    rootSpan.setAttribute('review.items', items.length);

    const catalogLines = (Array.isArray(productCatalog) ? productCatalog : [])
      .slice(0, 300) // cap p/ evitar overflow de token
      .map((p: { name?: string }) => String(p?.name ?? '').trim())
      .filter(Boolean)
      .join('\n');

    const itemLines = items
      .map(
        (it: { texto?: string; match?: string; categoria?: string }, i: number) =>
          `${i}. secao="${String(it?.categoria ?? '').replace(/"/g, "'")}" | texto="${String(it?.texto ?? '').replace(/"/g, "'")}" | match="${String(it?.match ?? '').replace(/"/g, "'")}"`,
      )
      .join('\n');

    const prompt = `[ITENS]\n${itemLines}\n\n[CATÁLOGO]\n${catalogLines}`;

    const llmSpan = tracer.startSpan('llm-call-openrouter', rootSpan.spanId);
    const llmStart = Date.now();
    const { content, model, usage } = await callWithFallback(prompt);
    const llmDurationMs = Date.now() - llmStart;
    llmSpan.setAttribute('llm.model', model);
    llmSpan.setAttribute('llm.provider', 'openrouter');
    if (usage) {
      const inputTokens = usage.prompt_tokens ?? 0;
      const outputTokens = usage.completion_tokens ?? 0;
      llmSpan.setAttribute('llm.usage.input_tokens', inputTokens);
      llmSpan.setAttribute('llm.usage.output_tokens', outputTokens);
      metrics.recordLlmCall({
        model,
        provider: 'openrouter',
        operation: 'match-review',
        inputTokens,
        outputTokens,
        durationMs: llmDurationMs,
      });
    }
    llmSpan.end();

    let parsed: { flags?: unknown };
    try {
      parsed = parseJson(content) as { flags?: unknown };
    } catch {
      console.warn('[review] parse fail', content?.slice?.(0, 300));
      parsed = { flags: [] };
    }
    const flags = Array.isArray(parsed?.flags) ? parsed.flags : [];
    rootSpan.setAttribute('review.flags', flags.length);
    rootSpan.end();
    Promise.all([tracer.flush(), metrics.flush()]).catch(() => {});

    return new Response(JSON.stringify({ flags, model }), {
      headers: { ...corsHeaders, 'Content-Type': 'application/json', 'traceparent': tracer.getResponseTraceparent() },
    });
  } catch (error) {
    console.error('[review] fatal', error);
    rootSpan.endWithError(error instanceof Error ? error.message : String(error));
    Promise.all([tracer.flush(), metrics.flush()]).catch(() => {});
    // Best-effort: nunca quebra o fluxo do frontend (review é opcional).
    return new Response(
      JSON.stringify({ flags: [], error: error instanceof Error ? error.message : String(error) }),
      { status: 200, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
    );
  }
});

