/**
 * Página /requisicoes/chegada — operador da loja confere a chegada das requisições.
 *
 * Mostra todas as requisições onde a loja_solicitante == loja do usuário
 * que ainda não foram concluídas (chegada_concluida_at IS NULL). Card-list,
 * cada card abre RequisicaoChegadaModal com os itens da requisição.
 */
import { useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import { ArrowLeft, Package, Truck, MapPin, Calendar, CheckCircle2, AlertTriangle } from "lucide-react";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";

import { Button } from "@/shared/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/shared/ui/card";
import { Badge } from "@/shared/ui/badge";
import { Skeleton } from "@/shared/ui/skeleton";
import { useStore } from "@/shared/contexts/StoreContext";
import { supabase } from "@/integrations/supabase/client";
import { cn } from "@/shared/lib/utils";
import {
  RequisicaoChegadaModal,
  type ChegadaItem,
} from "@/features/requisicoes/ui/RequisicaoChegadaModal";

interface ReqChegada {
  id: number;
  nome: string;
  loja_solicitante: string;
  loja_preparadora: string;
  data_pedido: string;
  data_recebimento: string;
  status: string | null;
  chegada_iniciada_at: string | null;
  chegada_concluida_at: string | null;
}

interface ProdutoNomeMap { id: number; nome: string; }

function fmtDate(iso: string | null): string {
  if (!iso) return "—";
  try {
    return format(new Date(iso), "dd/MM/yyyy", { locale: ptBR });
  } catch { return iso; }
}

export default function RequisicaoChegadaPage() {
  const navigate = useNavigate();
  const { selectedStore } = useStore();

  const [reqs, setReqs] = useState<ReqChegada[]>([]);
  const [loading, setLoading] = useState(true);
  const [modalOpen, setModalOpen] = useState(false);
  const [modalItems, setModalItems] = useState<ChegadaItem[]>([]);
  const [modalReq, setModalReq] = useState<ReqChegada | null>(null);

  // Loja atual: id + nome
  const [lojaId, setLojaId] = useState<number | null>(null);
  const [lojaNome, setLojaNome] = useState<string>("");

  useEffect(() => {
    if (!selectedStore) return;
    setLojaId(selectedStore.id);
    setLojaNome(selectedStore.name);
  }, [selectedStore]);

  const loadReqs = async () => {
    if (!lojaNome) return;
    setLoading(true);
    const { data, error } = await supabase
      .from("requisicoes")
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      .select("id, nome, loja_solicitante, loja_preparadora, data_pedido, data_recebimento, status, chegada_iniciada_at, chegada_concluida_at" as any)
      .ilike("loja_solicitante", `%${lojaNome}%`)
      .is("chegada_concluida_at", null)
      .order("data_recebimento", { ascending: true })
      .limit(50);
    if (error) {
      setLoading(false);
      return;
    }
    setReqs((data || []) as unknown as ReqChegada[]);
    setLoading(false);
  };

  useEffect(() => {
    if (lojaNome) loadReqs();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [lojaNome]);

  const openModal = async (req: ReqChegada) => {
